from collections import deque


def shortest_path(grid, start, goal):
    """Return the length of the shortest path through open cells, or -1.

    ``grid`` is a list of strings in which '#' marks a wall. Moves are
    horizontal or vertical, one cell at a time.
    """
    rows, cols = len(grid), len(grid[0])
    seen = {start}
    queue = deque([(start, 0)])
    while queue:
        (row, col), distance = queue.popleft()
        if (row, col) == goal:
            return distance
        for d_row, d_col in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nxt = (row + d_row, col + d_col)
            if not (0 <= nxt[0] < rows and 0 <= nxt[1] < cols):
                continue
            if grid[nxt[0]][nxt[1]] == '#' or nxt in seen:
                continue
            seen.add(nxt)
            queue.append((nxt, distance + 1))
    return -1


if __name__ == '__main__':
    maze = [
        '..#....',
        '.##.##.',
        '....#..',
        '#.#...#',
    ]
    print(shortest_path(maze, (0, 0), (3, 5)))
